fit_data_path = 'e:\SHARE\Fe\Data\analysis\06_fit_with_J0\Sym4D_cutsAndFits';
if ~exist('fit_resEi400','var')
    %fit_data_file = 'FitEn_cut200_1Dsbg_dirGH_dE20_fix_bg_slope.mat'; % fit 1D background with no Q-slope
    %fit_data_file = 'FitEn_cut200_1D_fit_bg_dirGH_dE20_fix_bg_slope.mat';%Externaly 2-exponent fit fixed bg at high momentum.                      
    fit_data_file = 'FitEn_cut400ref110_2D_dirGH_dE20_fix_bg_slope.mat';%Externaly 2-exponent fit fixed bg at high momentum.
    ld = load(fullfile(fit_data_path,fit_data_file));
    if isfield(ld,'fit_resEi400')
        fit_resEi400 = ld.fit_resEi400;        
    else
        fit_resEi400 = ld.fit_res;
    end
end
data_path = 'e:\SHARE\Fe\Data\analysis\06_fit_with_J0\sym4D_cutsAndFits';
fit_file = 'multicuts_fit_dataGH_ei400meV.mat';
if ~exist('cuts2fit400','var')
    ld = load(fullfile(data_path,fit_file));
    cuts2fit400 = ld.cuts2fit400;
end

mi = maps_instrument(400,600,'S');
sample=IX_sample(true,[1,0,0],[0,1,0],'cuboid',[0.04,0.03,0.02]);
cl = cuts2fit400.cutsF_list;
for i=1:numel(cl)
    cl{i} = cl{i}.set_instrument(mi);
    cl{i} = cl{i}.set_sample(sample);

    %cuts2fit.cutsS_list{i} = cuts2fit.cutsS_list{i}.set_instrument(mi);
    %cuts2fit.cutsS_list{i} = cuts2fit.cutsS_list{i}.set_sample(sample);
end
cuts2fit400.cut110_sel = cl{1};
cuts2fit = cuts2fit400;
fit_res = fit_resEi400;
%%
acolor g
Sgnl = fit_res.S;
pd(Sgnl);ly 0 2;liny;keep_figure %[output:5ad01664]
J0 = fit_res.J0;
pd(J0);ly 20 60;keep_figure %[output:008408ca]
% incorrect units fixture
G = fit_res.gamma;
G.s_axis.units = 'meV';
fit_res.gamma = G;
pd(G);ly 0 200;keep_figure %[output:38d0062e]

dE = min(Sgnl.x(2:end)-Sgnl.x(1:end-1)) %[output:9f0ab425]
e_min = Sgnl.x(1);

%%
En = 140 %[output:09903d81]
fit_par = fit_res.all_fit_par(1);
dE_step = fit_par.en_range(2); %original energy transfer step data were binned to. No point in going finer
half_dE = 0.5*(fit_par.en_range(3)-fit_par.en_range(1));
en_idx =  floor((En-e_min)/dE)+1;
%the2Dcuts = cuts2fit.cutsS_list;%(1:2);
the2Dcuts = {cut(cuts2fit.cut110_sel,[0,0.02,2],[])};%(1:2); %[output:13410c12]

%init_bg_params =
%cellfun(@(par)[par(1),par(3)],init_bg_params,'UniformOutput',false); % bg
%in case of 2-D fitting
%[fit_obj,fit_par,figa,figb]=fit_single_set(the2Dcuts,En,half_dE,dE_step,init_fg_params,init_bg_params,false)
lfit_par = fit_res.all_fit_par(en_idx);
en_range = lfit_par.en_range;
[fit_obj,fit_par,figa,figb]=refit_singleset_peaks(the2Dcuts,en_range,lfit_par,0.2,true,false); %[output:44554819] %[output:1bd75264] %[output:821660b7] %[output:108ff07b]
%%
%fit_res.all_fit_par(en_idx) = fit_par;
%fit_res.all_fit_par(en_idx).p = fit_par.p;
acolor r
plot(fit_res.S);ly 0 1.5;liny; %[output:481035d7]
acolor g
Sgnl.signal(en_idx) = fit_par.p(4);
pd(Sgnl);ly 0 1.5;liny;keep_figure %[output:481035d7]

acolor r
plot(fit_res.J0);ly 10 50;liny; %[output:77c1327c]
acolor g
J0.signal(en_idx) = fit_par.p(6);
pd(J0);ly 10 50;keep_figure %[output:77c1327c]

acolor r
plot(fit_res.gamma);ly 0 100;liny; %[output:1f6866a7]
acolor g
G.signal(en_idx) = fit_par.p(3);
pd(G);ly 0 100;keep_figure %[output:1f6866a7]
%%
[fit_res,Sg,J0,G] = refit_data_around_peaks(the2Dcuts,fit_res,0.2,true); %[output:9163fc87] %[output:0711ae5c] %[output:77220fcd] %[output:61de881b] %[output:303a3f2d] %[output:38537f09] %[output:22e3999d] %[output:85628ad2] %[output:565f67ad] %[output:4ec3d6eb] %[output:85d73e8e] %[output:31fe2e7c] %[output:6c60c166] %[output:18821621] %[output:2b9b04c4] %[output:4e5eaf20] %[output:53e9cfa4] %[output:809d9c40] %[output:4a369125] %[output:1c5e1d4b] %[output:79af14c5] %[output:0d357694] %[output:8365ea3b] %[output:8219fda5] %[output:236616e2] %[output:01b73ba5] %[output:691750ff] %[output:1f72b639] %[output:8e7628cf] %[output:2329cc9e] %[output:6fa9e9c4] %[output:6be51b5d] %[output:38bc7716] %[output:98d00470] %[output:63ba0b05] %[output:5f635c85] %[output:037dd28c] %[output:5d3bd225] %[output:053cbb43] %[output:22a1c891] %[output:819c183b] %[output:332583f8] %[output:70701924] %[output:9604ffd2] %[output:6c4f53a2] %[output:6a0f08ad] %[output:59e4f8dd] %[output:68f533fa] %[output:59efa8a7] %[output:29637337] %[output:71f789bc] %[output:790131f9] %[output:06938a27] %[output:12e96834] %[output:27b6c0f7] %[output:3f8df5ea] %[output:8bdc674f]
%%
acolor r
plot(fit_res.S);liny; %[output:64fae10a]
acolor g
pd(Sg);ly 0.5 2;liny;keep_figure %[output:64fae10a]

acolor r
plot(fit_res.J0);liny; %[output:1e23d8f3]
acolor g
pd(J0);ly 10 50;keep_figure %[output:1e23d8f3]

acolor r
plot(fit_res.gamma);liny; %[output:819161d3]
acolor g
pd(G);ly 0 200;keep_figure %[output:819161d3]
%%

%%
fit_res.Speak_varsl = Sg;
fit_res.J0peak_varsl = J0;
fit_res.gamma_peak_varsl = G;
