% fit_res.J0peak = J0;
% fit_res.gamma_peak = G;
fit_res.peak_fit_par = [peak_fit_par{:}];
fit_res.peak_fit_VarSlope_par = fit_res.peak_fit_par;
fit_resEi400 = fit_res;
save(fullfile(fit_data_path,fit_data_file),"fit_resEi400");

